112	  var STORAGE_KEY = 'todos';
113	
114	  function makeId() {
115	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
116	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
117	  }
118	
119	  function load() {
120	    try {
121	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
122	      return Array.isArray(data) ? data : [];
123	    } catch (e) {
124	      return [];
125	    }
126	  }
127	
128	  function save(todos) {
129	    try {
130	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
