242	      toggle.checked = completed;
243	      toggle.addEventListener('change', function () {
244	        todos = todos.map(function (t) {
245	          return t.id === todo.id ? Object.assign({}, t, { completed: toggle.checked }) : t;
246	        });
247	        save(todos);
248	        render();
249	      });
250	
251	      var text = document.createElement('span');
252	      text.className = 'text';
253	      text.setAttribute('data-testid', 'todo-text');
254	      text.textContent = todo.text;
255	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
256	
257	      var del = document.createElement('button');
258	      del.type = 'button';
259	      del.className = 'delete';
260	      del.setAttribute('data-testid', 'todo-delete');
261	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
262	      del.textContent = 'Delete';
263	      del.addEventListener('click', function () {
264	        todos = todos.filter(function (t) { return t.id !== todo.id; });
265	        save(todos);
266	        render();
267	      });
268	
269	      li.appendChild(toggle);
270	      li.appendChild(text);
271	      if (typeof todo.due === 'string' && DUE_PATTERN.test(todo.due)) {
272	        var due = document.createElement('span');
273	        due.className = 'due';
274	        due.setAttribute('data-testid', 'todo-due-date');
275	        due.textContent = (overdue ? 'Overdue · ' : 'Due ') + formatDue(todo.due);
276	        li.appendChild(due);
277	      }
278	      li.appendChild(del);
279	      list.appendChild(li);
280	    });
281	    empty.textContent = todos.length === 0 ? EMPTY_TEXT.none : search ? EMPTY_TEXT.search : (EMPTY_TEXT[filter] || '');
282	    empty.hidden = shown.length > 0;
283	  }
284	
285	  form.addEventListener('submit', function (event) {
286	    event.preventDefault();
287	    var value = input.value.trim();
288	    if (!value) return;
289	    var todo = { id: makeId(), text: value, createdAt: Date.now(), completed: false, priority: normalizePriority(priorityInput.value) };
290	    if (DUE_PATTERN.test(dueInput.value)) todo.due = dueInput.value;
291	    todos.push(todo);
292	    save(todos);
293	    input.value = '';
294	    dueInput.value = '';
295	    priorityInput.value = 'med';
296	    input.focus();
297	    render();
298	  });
299	
300	  // Today may have changed while the tab was hidden (e.g. overnight).
301	  document.addEventListener('visibilitychange', function () {
302	    if (!document.hidden) render();
303	  });
304	
305	  render();
306	</script>
